int main(){ll n,A,cf,cm,m;cin>>n>>A>>cf>>cm>>m;vector<pair<ll,int>>a(n);for(int i=0;i<n;i++){cin>>a[i].first;a[i].second=i;}
sort(a.begin(),a.end());vector<ll>pre(n+1,0);for(int i=0;i<n;i++)pre[i+1]=pre[i]+a[i].first;
ll best=-1,bk=0,bmin=0,suf=0; // k = number of top skills maxed
for(ll k=0;k<=n;k++){ if(k>0)suf+=A-a[n-k].first; if(suf>m)break; ll r=m-suf,mn;
  if(k==n)mn=A; else{ // largest p in [1,n-k] with a[p-1]*p-pre[p]<=r
    ll lo=1,hi=n-k;while(lo<hi){ll md=(lo+hi+1)/2;if(a[md-1].first*md-pre[md]<=r)lo=md;else hi=md-1;}
    mn=min(A,(r+pre[lo])/lo);}
  ll f=cf*k+cm*mn;if(f>best){best=f;bk=k;bmin=mn;}}
vector<ll>res(n);for(int i=0;i<n;i++){ll v=(i>=n-bk)?A:max(a[i].first,bmin);res[a[i].second]=v;}
cout<<best<<"\n";for(ll v:res)cout<<v<<" ";cout<<"\n";}

