#include <bits/stdc++.h>
using namespace std;
typedef long long ll;const ll M=1e9+7;
ll pw(ll b,ll e){ll r=1;b%=M;while(e){if(e&1)r=r*b%M;b=b*b%M;e>>=1;}return r;}
int main(){ll n,m,k;cin>>n>>m>>k;vector<vector<ll>>C(n+1,vector<ll>(n+1,0));
 for(int i=0;i<=n;i++){C[i][0]=1;for(int j=1;j<=i;j++)C[i][j]=(C[i-1][j-1]+C[i-1][j])%M;}
 ll q=m/n,rm=m%n; // residue r<rm appears q+1 times, else q
 vector<ll>P0(n+1),P1(n+1);for(int c=0;c<=n;c++){P0[c]=pw(C[n][c],q);P1[c]=pw(C[n][c],q+1);}
 vector<ll>dp(k+1,0);dp[0]=1;
 for(int r=0;r<n;r++){vector<ll>nd(k+1,0);auto&P=(r<rm)?P1:P0;
  for(int s=0;s<=k;s++)if(dp[s])for(int c=0;c<=n&&s+c<=k;c++)nd[s+c]=(nd[s+c]+dp[s]*P[c])%M;dp=nd;}
 cout<<dp[k]<<"\n";}

