using namespace std;
typedef long long ll;const ll M=1e9+7;ll cnt[11];
ll go(int left,int budget){ // ordered picks of `left` numbers with total lucky digits <= budget
 if(left==0)return 1;ll r=0;
 for(int l=0;l<=budget;l++)if(cnt[l]>0){ll c=cnt[l]--;r=(r+c%M*go(left-1,budget-l))%M;cnt[l]++;}
 return r;}
int main(){ll m;cin>>m;string s=to_string(m);int L=s.size();
 // digit DP: count numbers in [0,m] by number of lucky digits
 int tight=0;ll f[11]={0}; // f[k] counts free (non-tight) prefixes with k lucky
 // iterate digits; tightLucky = lucky count of m's prefix
 for(int i=0;i<L;i++){int d=s[i]-'0';ll g[11]={0};
  for(int k=0;k<=10;k++)if(f[k]){g[k]+=f[k]*8;if(k<10)g[k+1]+=f[k]*2;}
  for(int x=0;x<d;x++)g[tight+(x==4||x==7)]++;
  tight+=(d==4||d==7);memcpy(f,g,sizeof f);}
 f[tight]++;f[0]--; // include m itself, exclude 0
 memcpy(cnt,f,sizeof cnt);ll ans=0;
 for(int l=1;l<=10;l++)if(cnt[l]>0){ll c=cnt[l]--;ans=(ans+c%M*go(6,l-1))%M;cnt[l]++;}
 cout<<ans<<"\n";}

