int n;vector<string>c;static char vis[53][53][53][53];
bool ok(int a,int b){return c[a][0]==c[b][0]||c[a][1]==c[b][1];}
// i = number of piles; tops of piles i, i-1, i-2 are cards x,y,z; piles < i-2 are untouched
bool go(int i,int x,int y,int z){if(i==1)return true;char&v=vis[i][x][y][z];if(v)return v==1;bool r=false;
 if(ok(x,y))r=go(i-1,x,z,i>=4?i-4:0);           // put pile i on pile i-1
 if(!r&&i>=4&&ok(x,i-4))r=go(i-1,y,z,x);        // put pile i on pile i-3 (card index i-4)
 v=r?1:2;return r;}
int main(){cin>>n;c.resize(n);for(auto&s:c)cin>>s;
 if(n==1){puts("YES");return 0;}
 puts(go(n,n-1,n-2,n>=3?n-3:0)?"YES":"NO");}

