#include <bits/stdc++.h>
using namespace std;
int n,m;vector<string>g;
// clear(r1,c1,r2,c2): straight segment (horizontal/vertical/diagonal) has no black node, endpoints included
static int H[402][402],V[402][402],D1[402][402],D2[402][402];
bool clear(int r1,int c1,int r2,int c2){
 if(r1<0||r2<0||c1<0||c2<0||r1>=n||r2>=n||c1>=m||c2>=m)return false;
 if(r1==r2){if(c1>c2)swap(c1,c2);return H[r1][c2+1]-H[r1][c1]==0;}
 if(c1==c2){if(r1>r2)swap(r1,r2);return V[r2+1][c1]-V[r1][c1]==0;}
 if(r1>r2){swap(r1,r2);swap(c1,c2);}
 if(c2-c1==r2-r1)return D1[r2+1][c2+1]-D1[r1][c1]==0;        // down-right
 return D2[r2+1][c2]-D2[r1][c1+1]==0;}                        // down-left
int main(){cin>>n>>m;g.resize(n);for(auto&s:g)cin>>s;
 for(int i=0;i<n;i++)for(int j=0;j<m;j++){int b=g[i][j]=='1';H[i][j+1]=H[i][j]+b;V[i+1][j]=V[i][j]+b;D1[i+1][j+1]=D1[i][j]+b;D2[i+1][j]=D2[i][j+1]+b;}
 long long ans=0;int dy[2]={1,-1},dx[2]={1,-1};
 for(int i=0;i<n;i++)for(int j=0;j<m;j++){if(g[i][j]=='1')continue;
  for(int a=0;a<2;a++)for(int b=0;b<2;b++)for(int L=1;;L++){ // right angle at (i,j), axis legs
   if(!clear(i,j,i+dy[a]*L,j)||!clear(i,j,i,j+dx[b]*L))break;if(clear(i+dy[a]*L,j,i,j+dx[b]*L))ans++;}
  for(int a=0;a<2;a++)for(int L=1;;L++){ // right angle at (i,j), diagonal legs, horizontal hypotenuse
   if(!clear(i,j,i+dy[a]*L,j-L)||!clear(i,j,i+dy[a]*L,j+L))break;if(clear(i+dy[a]*L,j-L,i+dy[a]*L,j+L))ans++;}
  for(int b=0;b<2;b++)for(int L=1;;L++){ // diagonal legs, vertical hypotenuse
   if(!clear(i,j,i-L,j+dx[b]*L)||!clear(i,j,i+L,j+dx[b]*L))break;if(clear(i-L,j+dx[b]*L,i+L,j+dx[b]*L))ans++;}}
 cout<<ans<<"\n";}

