typedef long long ll;ll C[64][64];
ll countPop(ll N,int k){ // #x in [0,N] with popcount(x)==k
 ll r=0;int seen=0;for(int b=62;b>=0;b--)if(N>>b&1){if(k-seen>=0&&k-seen<=b)r+=C[b][k-seen];seen++;}
 if(seen==k)r++;return r;}
int main(){for(int i=0;i<64;i++){C[i][0]=1;for(int j=1;j<=i;j++)C[i][j]=C[i-1][j-1]+C[i-1][j];}
 ll n,t;cin>>n>>t;if(t&(t-1)){puts("0");return 0;}int k=__builtin_ctzll(t)+1; // need popcount(m+1) == log2(t)+1
 ll ans=countPop(n+1,k)-countPop(1,k);cout<<ans<<"\n";} // x = m+1 ranges over [2, n+1]

#include <bits/stdc++.h>
using namespace std;
int n,m;vector<string>g;int P[502][502];
int blacks(int r,int c,int s){return P[r+s][c+s]-P[r][c+s]-P[r+s][c]+P[r][c];}
int main(){cin>>n>>m;g.resize(n);for(auto&s:g)cin>>s;
 for(int i=0;i<n;i++)for(int j=0;j<m;j++)P[i+1][j+1]=P[i][j+1]+P[i+1][j]-P[i][j]+(g[i][j]=='*');
 // ok[mask][i][j]: square of size 2^lvl at (i,j) is the fractal of pattern mask after lvl steps
 vector<vector<vector<char>>>ok(16,vector<vector<char>>(n,vector<char>(m,0))),nk=ok;
 for(int i=0;i+2<=n;i++)for(int j=0;j+2<=m;j++){int mask=(g[i][j]=='*')|(g[i][j+1]=='*')<<1|(g[i+1][j]=='*')<<2|(g[i+1][j+1]=='*')<<3;ok[mask][i][j]=1;}
 long long ans=0;
 for(int s=4;s<=min(n,m);s*=2){int h=s/2;
  for(int mask=0;mask<16;mask++)for(int i=0;i+s<=n;i++)for(int j=0;j+s<=m;j++){bool good=true;
   for(int q=0;q<4&&good;q++){int r=i+(q>>1)*h,c=j+(q&1)*h;
    good=(mask>>q&1)?blacks(r,c,h)==h*h:ok[mask][r][c];} // black quadrant: all black; white: smaller fractal
   nk[mask][i][j]=good;}
  for(int i=0;i+s<=n;i++)for(int j=0;j+s<=m;j++){bool any=false;for(int mask=0;mask<16;mask++)any|=nk[mask][i][j];ans+=any;}
  swap(ok,nk);for(auto&a:nk)for(auto&b:a)fill(b.begin(),b.end(),0);}
 cout<<ans<<"\n";}

