 int best=-1;for(int s=odd;s>=0;s--)if(dp[c][s]&&tot-s<=even){best=s;break;}
 if(best<0){puts("-1");return 0;}
 int po=1,pe=2,s=best;
 for(int q=c-1;q>=0;q--){int id=two[q],w=k[id];if(s>=w&&dp[q][s-w]){ans[id]=po;po+=2*w;s-=w;}else{ans[id]=pe;pe+=2*w;}}
