const int LG=17;int n;vector<int>dep,sz;vector<array<int,LG>>up;
int anc(int v,int k){for(int b=0;b<LG;b++)if(k>>b&1)v=up[v][b];return v;}
int lca(int a,int b){if(dep[a]<dep[b])swap(a,b);a=anc(a,dep[a]-dep[b]);if(a==b)return a;for(int b2=LG-1;b2>=0;b2--)if(up[a][b2]!=up[b][b2]){a=up[a][b2];b=up[b][b2];}return up[a][0];}
int main(){scanf("%d",&n);vector<vector<int>>g(n+1);for(int i=0;i<n-1;i++){int a,b;scanf("%d %d",&a,&b);g[a].push_back(b);g[b].push_back(a);}
 dep.assign(n+1,0);sz.assign(n+1,1);up.assign(n+1,{});vector<int>ord{1};up[1].fill(1);
 vector<char>vis(n+1,0);vis[1]=1;
 for(size_t i=0;i<ord.size();i++){int u=ord[i];for(int w:g[u])if(!vis[w]){vis[w]=1;dep[w]=dep[u]+1;up[w][0]=u;ord.push_back(w);}}
 for(int b=1;b<LG;b++)for(int v=1;v<=n;v++)up[v][b]=up[up[v][b-1]][b-1];
 for(int i=n-1;i>0;i--)sz[up[ord[i]][0]]+=sz[ord[i]];
 int m;scanf("%d",&m);while(m--){int x,y;scanf("%d %d",&x,&y);
  if(x==y){printf("%d\n",n);continue;}int l=lca(x,y),d=dep[x]+dep[y]-2*dep[l];
  if(d%2){puts("0");continue;}if(dep[x]<dep[y])swap(x,y);
  if(dep[x]==dep[y]){int cx=anc(x,dep[x]-dep[l]-1),cy=anc(y,dep[y]-dep[l]-1);printf("%d\n",n-sz[cx]-sz[cy]);} // midpoint is the lca
  else{int mid=anc(x,d/2),c=anc(x,d/2-1);printf("%d\n",sz[mid]-sz[c]);}}}

